mapper.select:
SELECT * FROM group_message
WHERE group_id = #{groupId}
ORDER BY send_time DESC
    LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE group_message
SET recall_time = NOW()
WHERE id = #{messageId}
  AND from_user_id = #{userId}
  AND send_time > DATE_SUB(NOW(), INTERVAL 2 MINUTE)
